  <section class="lp-final" id="audit" data-lp-final>
    <div class="lp-wrap">
      <div class="lp-final__card">
        <span class="lp-kicker lp-kicker--lime">Free audit · Abu Dhabi &amp; Al Ain</span>
        <h2 class="lp-title">Find out how you look to Abu Dhabi clients <span style="color:var(--lime)">in Arabic and in English</span></h2>
